BELIAL_A4_PAYLOAD
EXPECTED='8c926be910a23531330ec72a4ca5eb2cf21c5c84b273dfd3f00f60fe3cda2235'
ACTUAL="$(sha256sum "$TMP/payload.tar.gz" | awk '{print $1}')"
[ "$ACTUAL" = "$EXPECTED" ] || { echo 'Payload A4 corrompido; nenhuma instalação iniciada.' >&2; exit 3; }
python3 - "$TMP/payload.tar.gz" "$TMP" <<'PY'
import pathlib,sys,tarfile
src=pathlib.Path(sys.argv[1]); dst=pathlib.Path(sys.argv[2]).resolve()
with tarfile.open(src,'r:gz') as t:
    members=t.getmembers()
    if not members: raise SystemExit('PAYLOAD_VAZIO')
    for m in members:
        p=pathlib.PurePosixPath(m.name)
        if p.is_absolute() or '..' in p.parts or not p.parts or p.parts[0] != 'BELIAL_A4_90M':
            raise SystemExit('MEMBRO_INSEGURO:'+m.name)
        if m.issym() or m.islnk() or m.isdev():
            raise SystemExit('TIPO_INSEGURO:'+m.name)
    t.extractall(dst,members=members,filter='data')
PY
ROOT="$TMP/BELIAL_A4_90M"
[ -f "$ROOT/MANIFEST_SHA256.json" ] || { echo 'Manifesto A4 ausente.' >&2; exit 3; }
export PYTHONDONTWRITEBYTECODE=1
export PYTHONUNBUFFERED=1
export PYTHONPATH="$ROOT"
if [ "$MODE" = "--verificar-pacote" ]; then
  cd "$ROOT"
  exec python3 -B -m a4.verify
fi
cd "$ROOT"
exec python3 -B -m a4.install
